-- 0157: construction arcs for نزل كتب عزز — every Qurʾānic use of the lemmas placed; one particle with several senses kept as branches — model كشف; every example checked in the muṣḥaf, every lemma in AL, every count against its verses.
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazala:lazim', 'نزل', '2800aea5ea522f1be1ab108d71', NULL, 'نَزَلَ لازمًا (مِن…)', NULL, 0, 4, '["17:105", "34:2", "57:4", "57:16"]', 'هُبوطُ شيءٍ من عُلْو ← وقوعُه في الأسفل', 'drop from a height → and arrive below', 'No object and nothing carried. In 34:2 and 57:4 مِن only marks where the fall starts (the sky). In 17:105 بِالْحَقِّ and 57:16 مِنَ الْحَقِّ only describe what came down. When بـ carries a thing down, see the next arc.', NULL, '[{"kind": "object_semantics", "label": "from_the_sky", "refs": ["34:2", "57:4"]}, {"kind": "object_semantics", "label": "revelation_came_down", "refs": ["17:105", "57:16"], "note_en": "بالحق / من الحق describe it; they do not govern"}]', '["lex:maqayis_lugha:blk_mqy_10f03d4ad9a42f6d", "lex:raghib_mufradat:blk_mfr_79c3b2acfeb750c2", "lex:fayyumi_misbah_munir:blk_msb_519bf288cdf8cbc4"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazala:bi_haml', 'نزل', '2800aea5ea522f1be1ab108d71', NULL, 'نَزَلَ بِـ + المحمول', 'بـ', 1, 1, '["26:193"]', 'هُبوطٌ ← مع حملِ شيءٍ ← إنزالُه', 'come down → carrying something, and so bring it down', 'The bāʾ makes the verb reach a thing (Zamakhsharī: للتعدية): نَزَلَ بِهِ = أَنْزَلَهُ, with the carrier (Jibrīl) as subject. In 17:105 وَبِالْحَقِّ نَزَلَ the bāʾ only goes along with the descent.', NULL, NULL, '["lex:fayyumi_misbah_munir:blk_msb_519bf288cdf8cbc4", "lex:raghib_mufradat:blk_mfr_495f43b2607331c2", "lex:raghib_mufradat:blk_mfr_28ab01f51759d9e2", "tafsir:zamakhshari:26:192"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazala:bi_makan', 'نزل', '2800aea5ea522f1be1ab108d71', NULL, 'نَزَلَ بِـ + مكان', 'بـ', 0, 1, '["37:177"]', 'هُبوطٌ ← حلولٌ بالمكان ← نزولُ البلاءِ بأهله', 'come down → and settle on a place, like an army at the gate', 'Here بـ names where it lands, not a thing carried. Said of the promised punishment; al-Ālūsī: pictured as an army falling on people in their homes.', NULL, NULL, '["lex:lane_lexicon:blk_lane_42178e76e6b1bbbf", "lex:ibn_manzur_lisan_arab:blk_lsn_584e798b850957b8", "lex:fayyumi_misbah_munir:blk_msb_045f52a76d789329", "tafsir:alusi:37:177", "tafsir:zamakhshari:37:177"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:ala', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ (على) + مفعول', 'على', 1, 42, '["2:57", "2:59", "2:91", "2:102", "2:231", "3:7", "3:72", "3:84", "3:154", "4:113", "5:114", "6:8", "6:91", "6:156", "6:157", "7:26", "7:160", "8:41", "9:26", "9:40", "9:97", "10:20", "11:12", "13:7", "13:27", "15:90", "16:64", "18:1", "20:2", "22:5", "25:21", "29:50", "29:51", "30:35", "36:28", "38:8", "39:41", "41:39", "48:18", "48:26", "59:21"]', 'إنزالٌ من عُلْو ← وقوعُه على المُنزَل عليه', 'send it down from above → so it lands on someone', 'على looks at where it comes from: above. إلى (next arc) looks at where it ends: with someone. Zamakhsharī and al-Rāzī on 3:84: revelation is both, so the Qurʾān uses one, then the other (3:84 عَلَيْنَا, 2:136 إِلَيْنَا). Rāghib''s finer rule — على for what reaches a prophet directly, إلى for what reaches the community through him — is reported by Abū Ḥayyān and al-Ālūsī; al-Ālūsī doubts it (3:72 has على of the believers).', NULL, '[{"kind": "object_semantics", "label": "revelation", "refs": ["2:91", "2:102", "2:231", "3:7", "3:72", "3:84", "4:113", "6:91", "6:156", "6:157", "8:41", "9:97", "16:64", "18:1", "20:2", "29:51", "38:8", "39:41", "59:21"]}, {"kind": "object_semantics", "label": "calm_and_safety", "refs": ["3:154", "9:26", "9:40", "48:18", "48:26"]}, {"kind": "object_semantics", "label": "food_cover_water", "refs": ["2:57", "5:114", "7:26", "7:160", "22:5", "41:39"], "note_en": "in 22:5 and 41:39 the receiver is the dead earth"}, {"kind": "object_semantics", "label": "punishment_or_force", "refs": ["2:59", "15:90", "36:28"]}, {"kind": "object_semantics", "label": "demanded_sign", "refs": ["6:8", "10:20", "11:12", "13:7", "13:27", "25:21", "29:50", "30:35"], "note_en": "لَوْلَا أُنزِلَ عَلَيْهِ … — the deniers ask for an angel, a sign, a treasure"}]', '["lex:zabidi_taj_arus:blk_taj_9305c0f0c8aa70ee", "lex:raghib_mufradat:blk_mfr_495f43b2607331c2", "tafsir:zamakhshari:3:84", "tafsir:razi:3:84", "tafsir:alusi:3:84", "tafsir:abu_hayyan:3:84"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:ila', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ (إلى) + مفعول', 'إلى', 1, 45, '["2:4", "2:99", "2:136", "2:285", "3:199", "4:60", "4:105", "4:162", "4:166", "4:174", "5:48", "5:49", "5:59", "5:64", "5:66", "5:67", "5:68", "5:81", "5:83", "6:114", "7:2", "7:3", "10:94", "13:1", "13:19", "13:36", "14:1", "16:44", "21:10", "24:34", "25:7", "28:24", "28:87", "29:46", "29:47", "34:6", "38:29", "39:2", "39:55", "65:5", "65:10"]', 'إنزالٌ ← انتهاؤه إلى المُنزَل إليه ← وصولُه إليه', 'send it down → until it reaches someone and is his to keep', NULL, NULL, '[{"kind": "object_semantics", "label": "good_sent_to_a_person", "refs": ["28:24"], "note_en": "Mūsā: ''whatever good You send down to me'' — not revelation"}]', '["lex:zabidi_taj_arus:blk_taj_9305c0f0c8aa70ee", "tafsir:zamakhshari:3:84", "tafsir:alusi:3:84", "lex:raghib_mufradat:blk_mfr_34b8d39d25e29bbf"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:direct', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ + مفعول (بلا مُنزَلٍ عليه)', NULL, 1, 59, '["2:4", "2:41", "2:90", "2:91", "2:159", "2:170", "2:174", "3:3", "3:4", "3:53", "3:65", "4:60", "4:61", "4:136", "4:162", "4:166", "5:44", "5:45", "5:47", "5:48", "5:49", "5:59", "5:104", "6:8", "6:91", "6:92", "6:93", "6:155", "9:26", "9:86", "9:124", "9:127", "11:14", "12:2", "13:37", "16:24", "16:30", "17:102", "17:105", "20:113", "21:50", "22:16", "23:24", "24:1", "24:46", "25:6", "31:21", "36:15", "41:14", "42:15", "42:17", "46:30", "47:9", "47:20", "57:25", "58:5", "64:8"]', 'إنزالٌ من عُلْو ← النظرُ إلى المُنزَلِ ومُنزِله ← المرجعُ الذي يُحكَم به', 'send down from above → the thing and its Sender only, held up as the measure', 'No receiver is named, so the sentence rests on the thing and the One who sent it: "what God sent down" becomes the rule to judge by and follow (5:44–49, 2:170). With iron, troops or angels (57:25, 9:26, 23:24) the books read it as made and given from above — Rāghib: sending down a thing, or its causes.', NULL, '[{"kind": "object_semantics", "label": "the_rule_to_judge_by", "refs": ["2:41", "2:90", "2:91", "2:159", "2:170", "2:174", "3:53", "4:61", "5:44", "5:45", "5:47", "5:48", "5:49", "5:104", "6:93", "16:24", "16:30", "17:102", "31:21", "36:15", "42:15", "47:9"]}, {"kind": "object_semantics", "label": "named_by_its_form", "refs": ["6:92", "6:155", "12:2", "13:37", "20:113", "21:50", "22:16", "24:1", "24:46", "58:5", "64:8"], "note_en": "a ḥāl or second word says what shape it came in: an Arabic Qurʾān, clear signs"}, {"kind": "object_semantics", "label": "sent_before", "refs": ["2:4", "3:3", "3:4", "3:65", "4:60", "4:136", "4:162", "5:59", "46:30"]}, {"kind": "object_semantics", "label": "made_and_given", "refs": ["6:8", "9:26", "23:24", "41:14", "57:25"], "note_en": "angels, unseen troops, iron"}]', '["lex:raghib_mufradat:blk_mfr_495f43b2607331c2", "lex:raghib_mufradat:blk_mfr_3688cab86a80c511", "lex:raghib_mufradat:blk_mfr_74dddc506a52d894", "lex:zabidi_taj_arus:blk_taj_41500f1fbd2675be"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:lam', 'نزل', 'd9dd34e69180a4fe29ded74142', 'fac2f894532e33e23e3e0b7b2e', 'أَنْزَلَ (لـ) + مفعول', 'لـ', 1, 4, '["10:59", "27:60", "39:6", "40:13"]', 'إنزالٌ ← لأجلِ المُنزَل له ← قَسْمٌ ورِزق', 'send down for someone → given out as his share', 'لـ names who benefits, not where it lands. Zamakhsharī on 39:6: أَنزَلَ لَكُم = decreed and shared out for you, since God''s decrees are said to come down; Ibn ʿĀshūr: لَكُم marks a favour. Cattle (39:6), provision (10:59), rain (27:60).', NULL, '[{"kind": "lemma", "label": "anzala", "refs": ["10:59", "27:60", "39:6"]}, {"kind": "lemma", "label": "nazzala", "refs": ["40:13"]}]', '["tafsir:zamakhshari:39:6", "tafsir:ibn_ashur:39:6", "lex:raghib_mufradat:blk_mfr_3d9f82019b891def", "lex:raghib_mufradat:blk_mfr_495f43b2607331c2"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:maa', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ (مع) + مفعول', 'مع', 1, 3, '["2:213", "7:157", "57:25"]', 'إنزالٌ ← مصاحبًا للرسل ← ليُحكَم به بين الناس', 'send down with someone → to travel at the messenger''s side', 'مَعَ is a ẓarf, not a ḥarf jarr, and names no receiver: the book is sent as the messengers'' companion (al-Ālūsī on 2:213: a ḥāl of the book — "joined to the prophets").', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_ebf70d5f2185dcc6", "tafsir:alusi:2:213", "tafsir:alusi:57:25", "tafsir:zamakhshari:2:213"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:bi_sultan', 'نزل', 'fac2f894532e33e23e3e0b7b2e', 'd9dd34e69180a4fe29ded74142', 'نَزَّلَ / أَنْزَلَ بِـ + سُلْطان (منفيًّا)', 'بـ', 1, 7, '["3:151", "6:81", "7:33", "7:71", "12:40", "22:71", "53:23"]', 'إنزالُ حُجّةٍ بالشيء ← نفيُها ← لا برهانَ له أصلًا', 'send down proof for a thing → and, denied, leave it with no warrant at all', 'All seven are negated (مَا لَمْ يُنَزِّلْ / مَا أَنزَلَ). The bāʾ ties the proof to the thing claimed (Zamakhsharī 12:40: بِهَا = for naming them). al-Ālūsī 7:33: the denial strikes both the sending and the proof. From tafsīr: the lexicons have نزل بـ only for Form I, "brought down".', NULL, '[{"kind": "lemma", "label": "nazzala", "refs": ["3:151", "6:81", "7:33", "7:71", "22:71"]}, {"kind": "lemma", "label": "anzala", "refs": ["12:40", "53:23"]}]', '["tafsir:zamakhshari:3:151", "tafsir:alusi:7:33", "tafsir:zamakhshari:7:33", "tafsir:zamakhshari:12:40", "tafsir:alusi:3:151"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:munzal', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَهُ مُنْزَلًا', NULL, 1, 1, '["23:29"]', 'حلولٌ ← إحلالُ الغيرِ منزلًا ← إضافتُه', 'set someone down → and lodge him as a guest', 'The object is a person and the next word is the lodging: the old sense of نزول, stopping at a place, made to happen to someone (Lane: أَنْزَلَهُ = he lodged him, made him his guest).', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_23d6290038a18493", "lex:lane_lexicon:blk_lane_c414883efd2ae1b4", "lex:jawhari_sihah:blk_sih_e3b06a4eae589f60", "lex:fayyumi_misbah_munir:blk_msb_771aa2f4e8b4a265"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:ala', 'نزل', 'fac2f894532e33e23e3e0b7b2e', NULL, 'نَزَّلَ (على) + مفعول', 'على', 1, 27, '["2:23", "2:90", "2:97", "2:105", "3:3", "4:136", "4:140", "4:153", "5:112", "6:7", "6:37", "8:11", "9:64", "15:6", "16:2", "16:89", "17:93", "17:95", "20:80", "25:1", "25:32", "26:4", "26:198", "30:49", "43:31", "47:2", "57:9"]', 'إنزالٌ من عُلْو ← على المُنزَل عليه ← مرّةً بعد مرّة', 'send down upon someone → piece after piece', 'Zamakhsharī (3:3): نَزَّلَ for the Qurʾān because it came in parts, أَنْزَلَ for the Torah and Gospel which came whole. But at 25:32 the deniers say نُزِّلَ … جُمْلَةً وَاحِدَةً, and Zamakhsharī must read نزّل there as plain أنزل; Abū Ḥayyān holds the doubled form is just a synonym of the hamza form. So "piece by piece" is the usual shade, not a fixed one (Tāj: the difference is "mostly").', NULL, '[{"kind": "object_semantics", "label": "revelation", "refs": ["2:23", "2:97", "3:3", "4:136", "4:140", "15:6", "16:89", "25:1", "25:32", "26:198", "43:31", "47:2", "57:9"]}, {"kind": "object_semantics", "label": "demanded_sign", "refs": ["4:153", "5:112", "6:7", "6:37", "9:64", "17:93", "17:95", "26:4"]}, {"kind": "object_semantics", "label": "bounty_food_rain", "refs": ["2:90", "2:105", "8:11", "20:80", "30:49"]}, {"kind": "object_semantics", "label": "angels_with_the_spirit", "refs": ["16:2"]}]', '["lex:raghib_mufradat:blk_mfr_c58dde854b5fd680", "lex:zabidi_taj_arus:blk_taj_41500f1fbd2675be", "lex:raghib_mufradat:blk_mfr_7d8663fd0bb6dfac", "tafsir:zamakhshari:3:3", "tafsir:zamakhshari:25:32", "tafsir:abu_hayyan:25:32"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:ila', 'نزل', 'fac2f894532e33e23e3e0b7b2e', NULL, 'نَزَّلَ (إلى) + مفعول', 'إلى', 1, 2, '["6:111", "16:44"]', 'إنزالٌ ← انتهاؤه إلى المُنزَل إليهم', 'send down → until it reaches them', 'Same split as أنزل على / إلى: إلى looks at the end point, the people reached.', NULL, NULL, '["lex:zabidi_taj_arus:blk_taj_9305c0f0c8aa70ee", "tafsir:zamakhshari:3:84"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:direct', 'نزل', 'fac2f894532e33e23e3e0b7b2e', NULL, 'نَزَّلَ + مفعول (بلا مُنزَلٍ عليه)', NULL, 1, 19, '["2:176", "3:93", "4:47", "5:101", "6:37", "7:196", "15:8", "15:9", "15:21", "16:101", "16:102", "17:82", "31:34", "39:23", "42:27", "42:28", "47:20", "47:26", "67:9"]', 'إنزالٌ مرّةً بعد مرّة ← النظرُ إلى المُنزَلِ ومُنزِله', 'send down, time after time → the thing and its Sender only', 'Rāghib on 47:20: the believers ask that a sūra be نُزِّلَت (sent bit by bit), and when one is أُنزِلَت (sent at once) the doubters shrink — both forms in one verse. With بِقَدَرٍ (15:21, 42:27) the sending is measured out.', NULL, '[{"kind": "object_semantics", "label": "revelation", "refs": ["2:176", "3:93", "4:47", "5:101", "7:196", "15:9", "16:101", "16:102", "17:82", "39:23", "47:20", "47:26", "67:9"]}, {"kind": "object_semantics", "label": "in_measure", "refs": ["15:21", "42:27"]}, {"kind": "object_semantics", "label": "rain", "refs": ["31:34", "42:28"]}, {"kind": "object_semantics", "label": "angels", "refs": ["15:8"]}, {"kind": "object_semantics", "label": "sign", "refs": ["6:37"]}]', '["lex:raghib_mufradat:blk_mfr_1ff112ef22fce379", "lex:raghib_mufradat:blk_mfr_6af202d9f1d5fd3f", "lex:raghib_mufradat:blk_mfr_f7bfb1f4ef723a46", "lex:ibn_manzur_lisan_arab:blk_lsn_73bfd00034d45440"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:min', 'نزل', 'fac2f894532e33e23e3e0b7b2e', NULL, 'نَزَّلَ (مِن السماء) + ماء', 'من', 1, 5, '["24:43", "29:63", "30:24", "43:11", "50:9"]', 'إنزالٌ ← من السماء ← مطرٌ وبَرَد', 'send down from the sky → rain, fall after fall', 'Same picture as أَنْزَلَ مِنَ السَّمَاءِ; 24:43 sends down hail from mountains of cloud.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_10f03d4ad9a42f6d", "lex:raghib_mufradat:blk_mfr_ea0db6fabe4ac1b3"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:nazzala:tanzilan', 'نزل', 'fac2f894532e33e23e3e0b7b2e', '1bc35f366d52a6776e838f0c4d', 'نَزَّلَ + تَنْزِيلًا (مفعولٌ مطلق)', NULL, 1, 3, '["17:106", "25:25", "76:23"]', 'تنزيلٌ ← توكيدُه بمصدره ← نَجْمًا بعد نَجْم', 'send down → and say it again with its own noun: step by step, over years', 'The verb''s own maṣdar follows it. Zamakhsharī: 17:106 "in step with events", 76:23 "in parts, spread out"; al-Ālūsī 76:23: over some twenty-three years. In 25:25 it is said of the angels on the Last Day.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_a91087f415d9df62", "lex:raghib_mufradat:blk_mfr_c58dde854b5fd680", "tafsir:zamakhshari:17:106", "tafsir:zamakhshari:76:23", "tafsir:alusi:76:23", "lex:ibn_manzur_lisan_arab:blk_lsn_81af6cc433a79027"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:tanazzala:ala', 'نزل', '05d62a0784bd84473542954971', NULL, 'تَنَزَّلَ (على)', 'على', 0, 3, '["26:221", "26:222", "41:30"]', 'نزولٌ في مُهلة ← على مَن يُنزَل عليه ← مرّةً بعد مرّة', 'come down by stages → and land on someone, again and again', 'Form V is نزول done slowly (Lisān: النزول في مهلة). على names who receives the visits: angels on the steadfast (41:30), devils on every liar (26:221–222).', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_50ab32962da20738", "lex:raghib_mufradat:blk_mfr_aa8ace397bef3a59", "lex:zabidi_taj_arus:blk_taj_cca1bc74788d0eef"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:tanazzala:bi', 'نزل', '05d62a0784bd84473542954971', NULL, 'تَنَزَّلَ بِـ + المحمول', 'بـ', 1, 1, '["26:210"]', 'نزولٌ في مُهلة ← حاملًا شيئًا', 'come down by stages → carrying something down', 'Rāghib: you say نَزَلَ الملَكُ بكذا and تَنَزَّلَ, never of God; and for lies and what comes from devils only تَنَزَّلَ is used. 26:210 denies that devils brought the Qurʾān down.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_9fca5b2ecca219c0", "lex:raghib_mufradat:blk_mfr_d2cc452e9510be66"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:tanazzala:lazim', 'نزل', '05d62a0784bd84473542954971', NULL, 'تَنَزَّلَ لازمًا', NULL, 0, 3, '["19:64", "65:12", "97:4"]', 'نزولٌ في مُهلة ← فوجًا بعد فوج ← بإذنٍ وأمر', 'come down slowly, in turns → by leave and by command', 'No receiver is named. What is named is the time (97:4 فِيهَا), the space (65:12 بَيْنَهُنَّ) or the order behind it (19:64 بِأَمْرِ رَبِّكَ).', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_3bd206b8bd0dbe59", "lex:raghib_mufradat:blk_mfr_0f16cb84bd2af4fc", "lex:raghib_mufradat:blk_mfr_1a3a6d898831a9dc", "lex:zabidi_taj_arus:blk_taj_cca1bc74788d0eef"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:tanzil:idafa_kitab', 'نزل', '1bc35f366d52a6776e838f0c4d', NULL, 'تَنْزِيلُ الكِتابِ + مِن', 'من', 1, 5, '["32:2", "39:1", "40:2", "45:2", "46:2"]', 'التنزيلُ ← مضافًا إلى ما نُزِّل ← ومِن مُنزِله', 'the sending-down of the Book → and where it comes from', 'The iḍāfa goes to the thing sent (the Book); مِن then names the Sender (Zamakhsharī 39:1: the jārr belongs to التنزيل, "as you say: it came down from God"). In 32:2 لَا رَيْبَ فِيهِ stands between them.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_79c3b2acfeb750c2", "lex:fayyumi_misbah_munir:blk_msb_519bf288cdf8cbc4", "lex:ibn_manzur_lisan_arab:blk_lsn_f7225aaec97b73eb", "tafsir:zamakhshari:39:1", "tafsir:zamakhshari:32:2"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:tanzil:munazzal', 'نزل', '1bc35f366d52a6776e838f0c4d', NULL, 'تَنْزِيلٌ مِن + المُنزِل / تَنْزِيلُ + المُنزِل', 'من', 0, 7, '["20:4", "26:192", "36:5", "41:2", "41:42", "56:80", "69:43"]', 'التنزيلُ ← مصدرٌ بمعنى المفعول ← المُنزَلُ من عند الله', 'a sending-down, named by its Sender → so it means "what He sent down"', 'Here the Book is not named; the Sender is — after مِن (20:4, 41:2, 41:42, 56:80, 69:43) or as the second term of the iḍāfa (26:192, 36:5). The maṣdar then stands for its object: Zamakhsharī 26:192 "التنزيل: المنزل"; al-Ālūsī 36:5 "المصدر بمعنى المفعول".', NULL, '[{"kind": "form", "label": "min_sender", "refs": ["20:4", "41:2", "41:42", "56:80", "69:43"]}, {"kind": "form", "label": "idafa_to_sender", "refs": ["26:192", "36:5"]}]', '["tafsir:zamakhshari:26:192", "tafsir:alusi:36:5", "tafsir:zamakhshari:41:2", "tafsir:zamakhshari:20:4"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:direct', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ + مفعول', NULL, 1, 17, '["2:79", "2:282", "3:181", "4:81", "10:21", "19:79", "36:12", "43:19", "43:80", "52:41", "68:47"]', 'ضمُّ الحروفِ بالخطّ ← تقييدُ الكلامِ والأعمال ← إثباتُها', 'join letter to letter → and so set words, or deeds, down on record', 'No harf: the verb reaches only the thing written. Real writing in 2:79 and 2:282 (a debt). In 3:181, 19:79, 36:12 and others God or His messengers record what people say and do — Rāghib: fixed for him and repaid. 52:41 and 68:47 (فَهُمْ يَكْتُبُونَ) Rāghib reads as a claim to sure knowledge.', NULL, '[{"kind": "object_semantics", "label": "write_a_document", "refs": ["2:79", "2:282"]}, {"kind": "object_semantics", "label": "record_words_and_deeds", "refs": ["3:181", "4:81", "10:21", "19:79", "36:12", "43:19", "43:80"]}, {"kind": "object_semantics", "label": "claim_to_know_the_unseen", "refs": ["52:41", "68:47"]}]', '["lex:raghib_mufradat:blk_mfr_264d0df9e2c3c510", "lex:lane_lexicon:blk_lane_da53f96abbcf8204", "lex:raghib_mufradat:blk_mfr_7c9b8e061243e4d2", "lex:raghib_mufradat:blk_mfr_a58015dad8f5b577", "lex:raghib_mufradat:blk_mfr_7b25560e5c3d3d01"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:ala', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ (على) + مفعول', 'على', 1, 18, '["2:178", "2:180", "2:183", "2:216", "2:246", "3:154", "4:66", "4:77", "5:32", "5:45", "6:12", "6:54", "22:4", "57:27", "59:3"]', 'الكتابةُ ← إثباتُ الأمرِ على المكتوبِ عليه ← فرضٌ أو قضاء', 'write it down over someone → so it binds him: a duty, or a fate', 'على puts the writing over the person as a weight. Most are law (fasting, fighting, retaliation). 3:154 and 59:3 are fate (death, exile — Rāghib: القضاء الممضى). In 6:12 and 6:54 God writes mercy "on Himself": He binds Himself to it.', NULL, '[{"kind": "object_semantics", "label": "law", "refs": ["2:178", "2:180", "2:183", "2:216", "2:246", "4:66", "4:77", "5:32", "5:45", "57:27"]}, {"kind": "object_semantics", "label": "fate", "refs": ["3:154", "22:4", "59:3"]}, {"kind": "object_semantics", "label": "on_himself", "refs": ["6:12", "6:54"]}]', '["lex:lane_lexicon:blk_lane_097e59301c780e4f", "lex:lane_lexicon:blk_lane_03ca330ba86afb8c", "lex:raghib_mufradat:blk_mfr_ff685f977a7ac053", "lex:raghib_mufradat:blk_mfr_a58015dad8f5b577", "lex:raghib_mufradat:blk_mfr_0ca2b5f49fcafbbd", "lex:zamakhshari_asas_balagha:blk_asb_ktb_p4", "lex:ibn_manzur_lisan_arab:blk_lsn_a98d2ea97ab97a88"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:lam', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ (لـ) + مفعول', 'لـ', 1, 8, '["2:187", "4:127", "5:21", "7:156", "9:51", "9:120", "9:121"]', 'الكتابةُ ← للمكتوبِ له ← قسمةٌ ونفع', 'write it down for someone → so it is his: a share, a gift, a credit', 'Rāghib on 9:51: "for us", not "against us" — whatever befalls us we count as grace; on 5:21: لَكُمْ not عَلَيْكُمْ, because entering the land would do them good. In 9:120–121 the لـ credits a deed to their account.', NULL, '[{"kind": "object_semantics", "label": "share_or_gift", "refs": ["2:187", "4:127", "5:21", "7:156", "9:51"]}, {"kind": "object_semantics", "label": "credit", "refs": ["9:120", "9:121"]}]', '["lex:raghib_mufradat:blk_mfr_f658124b17f4254a", "lex:raghib_mufradat:blk_mfr_934efdee292ec949", "lex:raghib_mufradat:blk_mfr_a1f427fd32d52c66", "lex:zamakhshari_asas_balagha:blk_asb_ktb_p4", "tafsir:zamakhshari:9:120"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:fi', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ (في) + مفعول', 'في', 1, 3, '["7:145", "21:105", "58:22"]', 'الكتابةُ ← في وعاءٍ ← رسوخُها فيه', 'write into something → so it stays fixed there: tablets, a scripture, a heart', 'Rāghib on 58:22: hearts written in are the opposite of the heart "left blank" (أَغْفَلْنَا) in 18:28.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_1fc34abd03346b30", "lex:raghib_mufradat:blk_mfr_aa94ca778b470433", "lex:raghib_mufradat:blk_mfr_165e9b1503036d02", "lex:raghib_mufradat:blk_mfr_984f11944d57b162"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:maa', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ + مفعول + مَعَ', 'مع', 1, 2, '["3:53", "5:83"]', 'الكتابةُ ← إثباتُ الاسمِ في جملةِ قوم ← عدُّه منهم', 'write a name down with others → count him as one of them', 'مَعَ is a ẓarf, not a ḥarf jarr. Rāghib on 3:53: "place us in their company".', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_fcdcab59ebaa4639", "lex:ibn_manzur_lisan_arab:blk_lsn_0560e7c741b730f8", "lex:lane_lexicon:blk_lane_08d8920bc2fc7381"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kataba:qasam', 'كتب', 'd58ea72c63c320ebac8252b29a', NULL, 'كَتَبَ + جوابُ قَسَم', NULL, 1, 1, '["58:21"]', 'الإرادةُ مبدأ ← الكتابةُ منتهى ← قضاءٌ مؤكَّدٌ كالقَسَم', 'write it down → as a sworn decree that must come true', 'No على or لـ: what is written is a sworn sentence (لَأَغْلِبَنَّ). al-Ālūsī: كَتَبَ here "runs like an oath". Rāghib: a thing is willed, then said, then written — writing is the last and firmest step.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_984f11944d57b162", "tafsir:alusi:58:21", "tafsir:zamakhshari:58:21"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kitab:ala', 'كتب', '26ec9894256ccd2fcb77820470', NULL, 'كِتاب (على)', 'على', 0, 2, '["4:24", "4:103"]', 'الكتابُ مصدرًا ← مكتوبًا على الناس ← فريضة', 'a writing → laid on people as a fixed duty', 'Not "a book": with على the noun keeps its maṣdar force. 4:24 كِتَابَ اللَّهِ عَلَيْكُمْ — Zamakhsharī: an emphatic maṣdar, "God wrote it on you". 4:103: prayer is a كِتَاب on the believers, bound to set times.', NULL, NULL, '["lex:lane_lexicon:blk_lane_49f7d6b71508b481", "lex:raghib_mufradat:blk_mfr_7a5a3875e71ecdc9", "tafsir:zamakhshari:4:24", "tafsir:zamakhshari:4:103"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:كتب:kitab:lam', 'كتب', '26ec9894256ccd2fcb77820470', NULL, 'لِـ + كِتاب', 'لـ', 0, 2, '["13:38", "15:4"]', 'الكتابُ ← مكتوبٌ لكلّ شيء ← أجلٌ محدود', 'a writing → set down for each thing as its fixed term', 'لـ names whose term it is (every term, every town). The same "written term" shows in other frames — 3:145 كِتَابًا مُّؤَجَّلًا, 2:235 حَتَّىٰ يَبْلُغَ الْكِتَابُ أَجَلَهُ — not counted here.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_7ec37251e9346905", "tafsir:zamakhshari:15:4", "tafsir:alusi:13:38"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aziz:allah', 'عزز', '3d42f257c274c5d8463f1b8371', NULL, 'العَزِيز صفةً لله', NULL, 0, 88, '["2:129", "2:209", "2:220", "2:228", "2:240", "2:260", "3:4", "3:6", "3:18", "3:62", "3:126", "4:56", "4:158", "4:165", "5:38", "5:95", "5:118", "6:96", "8:10", "8:49", "8:63", "8:67", "9:40", "9:71", "11:66", "14:1", "14:4", "14:47", "16:60", "22:40", "22:74", "26:9", "26:68", "26:104", "26:122", "26:140", "26:159", "26:175", "26:191", "26:217", "27:9", "27:78", "29:26", "29:42", "30:5", "30:27", "31:9", "31:27", "32:6", "33:25", "34:6", "34:27", "35:2", "35:28", "36:5", "36:38", "38:9", "38:66", "39:1", "39:5", "39:37", "40:2", "40:8", "40:42", "41:12", "42:3", "42:19", "43:9", "44:42", "45:2", "45:37", "46:2", "48:7", "48:19", "54:42", "57:1", "57:25", "58:21", "59:1", "59:23", "59:24", "60:5", "61:1", "62:1", "62:3", "64:18", "67:2", "85:8"]', 'أرضٌ عَزازٌ صُلبة ← حالةٌ مانعةٌ من الغلبة ← الذي يَغلِبُ ولا يُغلَب', 'ground too hard to break → the One who overcomes and is never overcome', 'No harf. It stands alone or, most often, paired with a second name — wise, merciful, knowing, forgiving — so might is never shown without what guides it. Rāghib: العزيز is "who overcomes and is not overcome".', NULL, '[{"kind": "paired_name", "label": "with_hakim", "refs": ["2:129", "2:209", "2:220", "2:228", "2:240", "2:260", "3:6", "3:18", "3:62", "3:126", "4:56", "4:158", "4:165", "5:38", "5:118", "8:10", "8:49", "8:63", "8:67", "9:40", "9:71", "14:4", "16:60", "27:9", "29:26", "29:42", "30:27", "31:9", "31:27", "34:27", "35:2", "39:1", "40:8", "42:3", "45:2", "45:37", "46:2", "48:7", "48:19", "57:1", "59:1", "59:24", "60:5", "61:1", "62:1", "62:3", "64:18"]}, {"kind": "paired_name", "label": "with_rahim", "refs": ["26:9", "26:68", "26:104", "26:122", "26:140", "26:159", "26:175", "26:191", "26:217", "30:5", "32:6", "36:5", "44:42"]}, {"kind": "paired_name", "label": "after_qawiyy", "refs": ["11:66", "22:40", "22:74", "33:25", "42:19", "57:25", "58:21"]}, {"kind": "paired_name", "label": "with_alim", "refs": ["6:96", "27:78", "36:38", "40:2", "41:12", "43:9"]}, {"kind": "paired_name", "label": "dhu_intiqam", "refs": ["3:4", "5:95", "14:47", "39:37"]}, {"kind": "paired_name", "label": "with_hamid", "refs": ["14:1", "34:6", "85:8"]}, {"kind": "paired_name", "label": "with_ghaffar", "refs": ["38:66", "39:5", "40:42"]}, {"kind": "paired_name", "label": "with_ghafur", "refs": ["35:28", "67:2"]}, {"kind": "paired_name", "label": "with_wahhab", "refs": ["38:9"]}, {"kind": "paired_name", "label": "with_muqtadir", "refs": ["54:42"]}, {"kind": "paired_name", "label": "in_list_with_jabbar", "refs": ["59:23"]}]', '["lex:raghib_mufradat:blk_mfr_7fa2a539db26bd47", "lex:raghib_mufradat:blk_mfr_7f8e4657b836642b", "lex:maqayis_lugha:blk_mqy_8fe7eb7954f82d33", "lex:lane_lexicon:blk_lane_8d9528f4ef4f0b4e"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aziz:insan', 'عزز', '3d42f257c274c5d8463f1b8371', NULL, 'العَزِيز / أَعِزَّة لإنسان (بلا على)', NULL, 0, 6, '["12:30", "12:51", "12:78", "12:88", "27:34", "44:49"]', 'المَنَعة ← لمن له سلطانٌ في قومه ← لقبُ الحاكم', 'might among men → the man in power; in Egypt, a ruler''s title', 'Said of people it names rank, not God''s might. Zamakhsharī 12:30: العزيز = the king, in the Arabs'' tongue. 27:34: the powerful of a town. 44:49 is mockery — the man who called himself mighty and noble is told so in Hell (Ibn ʿĀshūr: meant as its opposite).', NULL, '[{"kind": "object_semantics", "label": "title_of_egypts_ruler", "refs": ["12:30", "12:51", "12:78", "12:88"]}, {"kind": "object_semantics", "label": "the_powerful_of_a_town", "refs": ["27:34"], "note_en": "plural أَعِزَّة in iḍāfa"}, {"kind": "rhetoric", "label": "mockery", "refs": ["44:49"]}]', '["lex:lane_lexicon:blk_lane_5ee5463609d73259", "lex:raghib_mufradat:blk_mfr_eb8e9fcdc7e20102", "tafsir:zamakhshari:12:30", "tafsir:alusi:12:30", "tafsir:ibn_ashur:44:49", "tafsir:abu_hayyan:44:49"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aziz:shay', 'عزز', '3d42f257c274c5d8463f1b8371', NULL, 'عَزِيز صفةً لشيء', NULL, 0, 2, '["41:41", "48:3"]', 'الصلابة ← ما يصعبُ منالُه ← ما لا يُغلَب ولا يُنقَض', 'hard to reach → a book none can match, a victory none can undo', NULL, NULL, NULL, '["lex:raghib_mufradat:blk_mfr_e5f8429e986c7986", "lex:raghib_mufradat:blk_mfr_692b57841ecbb217", "lex:lane_lexicon:blk_lane_077d59e66c87092f", "tafsir:zamakhshari:48:3"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aazz:tafdil', 'عزز', '8387821b5791753bc271deee2a', NULL, 'أَعَزُّ (تمييزًا / مُطلقًا)', NULL, 0, 2, '["18:34", "63:8"]', 'العزّة ← تفضيل ← الأقوى منعةً', 'mightier → the one with more men behind him', 'Without على. 18:34 أَعَزُّ نَفَرًا (Zamakhsharī: more helpers and retinue). 63:8 الْأَعَزُّ is the hypocrite''s name for himself, answered at once: وَلِلَّهِ الْعِزَّةُ. With على (11:92) see the "dear to" arc.', NULL, NULL, '["lex:lane_lexicon:blk_lane_84f06fc55035334b", "tafsir:zamakhshari:18:34", "tafsir:zamakhshari:63:8"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aazza:fil', 'عزز', 'da839bbeae2e7a23e7ede773e8', NULL, 'أَعَزَّ + مفعول', NULL, 1, 1, '["3:26"]', 'العزّة ← جعلُ الغيرِ عزيزًا ← رفعُه', 'make someone mighty → raise him where none can bring him down', 'Form IV passes the state on to someone; in 3:26 paired with تُذِلُّ, bring low.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_75c60727551ed388", "lex:maqayis_lugha:blk_mqy_dc91f20a5218f291", "lex:lane_lexicon:blk_lane_9cbfbbcf02cbc97f"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:azzaza:bi', 'عزز', 'd0679f2fe2d659c5b9876f8576', NULL, 'عَزَّزَ (بـ)', 'بـ', 0, 1, '["36:14"]', 'الشدّة ← تقويةُ الشيء ← بضمِّ غيرِه إليه', 'make strong → by putting another at someone''s side', 'The object (the two messengers) is left out; Zamakhsharī: because the point is the one added. Also read عَزَزْنَا, "We overpowered them by a third".', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_5a64387fa012a804", "lex:lane_lexicon:blk_lane_9cbfbbcf02cbc97f", "tafsir:zamakhshari:36:14"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:azza:fi', 'عزز', '56834f34c3fa485855e9f3993f', NULL, 'عَزَّهُ (في)', 'في', 1, 1, '["38:23"]', 'الغلبة ← في مجالٍ بعينه ← غلبةٌ في الخطاب', 'be harder than someone → beat him in a field: here, in argument', NULL, NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_1c00032d474e4f82", "lex:lane_lexicon:blk_lane_e3dd3354e6748ac6", "lex:zabidi_taj_arus:blk_taj_032c52f08b8866fd", "lex:raghib_mufradat:blk_mfr_e0a18bdea44c5e13", "lex:raghib_mufradat:blk_mfr_71b667888a9d6383"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:min', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ (مِن السماء) + ماء / أَنْزَلَهُ مِن + مكانٍ عالٍ', 'من', 1, 22, '["2:22", "2:164", "6:99", "7:57", "10:24", "13:17", "14:32", "15:22", "16:10", "16:65", "18:45", "20:53", "22:63", "23:18", "25:48", "31:10", "35:27", "39:21", "45:5", "56:69", "78:14", "33:26"]', 'إنزالٌ من عُلْو ← من السماءِ والسحاب ← المطر', 'send down from the sky → as rain on the ground', 'One particle, several senses, told apart by what it governs: (1) send down from the sky → as rain on the ground; (2) bring someone down → off the high place that kept him safe.', NULL, '[{"kind": "sense", "label": "min", "arc_en": "send down from the sky → as rain on the ground", "arc_ar": "إنزالٌ من عُلْو ← من السماءِ والسحاب ← المطر", "note_en": "من names the starting point, so the descent is literal: water from sky or cloud (78:14 الْمُعْصِرَات, 56:69 الْمُزْن). 7:57 has بِهِ instead of مِن — Zamakhsharī: at the land, or by means of the cloud — and is kept here because the thing and the motion are the same.", "refs": ["2:22", "2:164", "6:99", "7:57", "10:24", "13:17", "14:32", "15:22", "16:10", "16:65", "18:45", "20:53", "22:63", "23:18", "25:48", "31:10", "35:27", "39:21", "45:5", "56:69", "78:14"]}, {"kind": "sense", "label": "min_shakhs", "arc_en": "bring someone down → off the high place that kept him safe", "arc_ar": "هُبوطٌ ← إحطاطُ الغيرِ من عُلْو ← إخراجُه من حِصنه", "note_en": null, "refs": ["33:26"]}, {"kind": "harf_variant", "label": "bi_instead_of_min", "refs": ["7:57"], "note_en": "بِهِ = at the land, or by the cloud (Zamakhsharī)"}, {"kind": "object_semantics", "label": "rain_called_provision", "refs": ["45:5"]}]', '["lex:maqayis_lugha:blk_mqy_10f03d4ad9a42f6d", "lex:raghib_mufradat:blk_mfr_ea0db6fabe4ac1b3", "lex:raghib_mufradat:blk_mfr_9c1750575092408a", "lex:zabidi_taj_arus:blk_taj_41500f1fbd2675be", "tafsir:zamakhshari:7:57", "lex:zabidi_taj_arus:blk_taj_cca1bc74788d0eef", "tafsir:zamakhshari:33:26", "tafsir:ibn_ashur:33:26"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:نزل:anzala:fi', 'نزل', 'd9dd34e69180a4fe29ded74142', NULL, 'أَنْزَلَ + ـه (في) + زمان / أَنْزَلَ + مفعول (في) + وعاء', 'في', 1, 6, '["2:185", "44:3", "97:1", "5:47", "24:1", "48:4"]', 'إنزالٌ ← في وقتٍ معيَّن ← دفعةً واحدة', 'send down → at one set time, all at once', 'One particle, several senses, told apart by what it governs: (1) send down → at one set time, all at once; (2) send down → and set it inside something: a heart, a book.', NULL, '[{"kind": "sense", "label": "fi_zaman", "arc_en": "send down → at one set time, all at once", "arc_ar": "إنزالٌ ← في وقتٍ معيَّن ← دفعةً واحدة", "note_en": "Always أنزل, never نزّل, in these three. Rāghib and the Tāj tie this to the report that the whole Qurʾān came down at once to the nearest heaven on that night, and then came down in parts.", "refs": ["2:185", "44:3", "97:1"]}, {"kind": "sense", "label": "fi_wia", "arc_en": "send down → and set it inside something: a heart, a book", "arc_ar": "إنزالٌ ← في داخلِ وعاءٍ ← ثبوتُه فيه", "note_en": "في here holds the thing; it does not date it. 48:4: al-Ālūsī — sending calm down into hearts means creating it there, and the word \"send down\" shows its high worth. 5:47 and 24:1: what was put inside a scripture or a sūra.", "refs": ["5:47", "24:1", "48:4"]}, {"kind": "object_semantics", "label": "into_hearts", "refs": ["48:4"]}, {"kind": "object_semantics", "label": "into_a_scripture", "refs": ["5:47", "24:1"]}]', '["lex:raghib_mufradat:blk_mfr_eac4a5fec038980b", "lex:raghib_mufradat:blk_mfr_e79c4364e156b93a", "lex:zabidi_taj_arus:blk_taj_41500f1fbd2675be", "tafsir:alusi:48:4", "tafsir:zamakhshari:48:4"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:عزز:aziz:ala', 'عزز', '3d42f257c274c5d8463f1b8371', NULL, 'عَزِيزٌ على + شخص (والمُخبَرُ عنه أمر) / عَزِيزٌ / أَعَزُّ على + شخص (والمُخبَرُ عنه إنسان) / أَعِزَّةٌ على + قوم', 'على', 0, 6, '["9:128", "14:20", "35:17", "11:91", "11:92", "5:54"]', 'الشدّة ← وقوعُها على النفس ← صعوبةُ الأمرِ عليه', 'hardness → a matter that is hard on someone, that weighs on him', 'One particle, several senses, told apart by what it governs: (1) hardness → a matter that is hard on someone, that weighs on him; (2) weight → a person who counts with you, too dear to harm; (3) hardness → hard against the enemy, never giving way.', NULL, '[{"kind": "sense", "label": "ala_amr", "arc_en": "hardness → a matter that is hard on someone, that weighs on him", "arc_ar": "الشدّة ← وقوعُها على النفس ← صعوبةُ الأمرِ عليه", "note_en": "The subject is a matter, not a person: 9:128 your hardship weighs on the Prophet; 14:20 and 35:17 (denied) replacing you is no weight for God.", "refs": ["9:128", "14:20", "35:17"]}, {"kind": "sense", "label": "ala_shakhs", "arc_en": "weight → a person who counts with you, too dear to harm", "arc_ar": "المَنَعة ← عند قومٍ ← كرامةٌ تمنعُ من الأذى", "note_en": "Same على, but the subject is a person, so the sense turns from \"hard on you\" to \"dear to you\". Zamakhsharī 11:91: لا تعزّ علينا ولا تكرم — you are not one we would spare. Shuʿayb answers in 11:92: is my clan dearer to you than God?", "refs": ["11:91", "11:92"]}, {"kind": "sense", "label": "ala_qawm", "arc_en": "hardness → hard against the enemy, never giving way", "arc_ar": "الصلابة ← في وجهِ العدوّ ← شدّةٌ عليه", "note_en": "على here is \"against\". Set beside أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ: soft toward believers, hard toward deniers. Zamakhsharī compares أَشِدَّاءُ عَلَى الْكُفَّارِ.", "refs": ["5:54"]}, {"kind": "polarity", "label": "affirmed", "refs": ["9:128"]}, {"kind": "polarity", "label": "denied_of_god", "refs": ["14:20", "35:17"]}, {"kind": "lemma", "label": "aziz", "refs": ["11:91"]}, {"kind": "lemma", "label": "aazz", "refs": ["11:92"]}]', '["lex:raghib_mufradat:blk_mfr_f290d0022f9db725", "lex:lane_lexicon:blk_lane_72c63ac730f5db54", "lex:ibn_manzur_lisan_arab:blk_lsn_1964482f58cbb9c1", "lex:maqayis_lugha:blk_mqy_0460496cceae2186", "lex:lane_lexicon:blk_lane_973f2ed820125c5a", "tafsir:zamakhshari:11:91", "tafsir:alusi:11:91", "tafsir:alusi:11:92", "lex:lane_lexicon:blk_lane_263eaa84bec7d5fe", "lex:lane_lexicon:blk_lane_d33dcab293c4e78d", "lex:lane_lexicon:blk_lane_fa01b72b2f7aec89", "tafsir:zamakhshari:5:54", "tafsir:alusi:5:54"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:34:2:nazala_lazim', 'ARC:نزل:nazala:lazim', '34:2', 34, 2, 'وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعۡرُجُ فِيهَا', 'and what comes down from the sky, and what climbs up into it', 'the bare verb: a fall from above, with مِن marking only where it starts', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:193:nazala_bi_haml', 'ARC:نزل:nazala:bi_haml', '26:193', 26, 193, 'نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِينُ', 'the Trustworthy Spirit brought it down', 'بِهِ makes the coming-down carry something: the angel comes, and the Qurʾān comes with him', 1, 'tafsir:zamakhshari:26:192', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:37:177:nazala_bi_makan', 'ARC:نزل:nazala:bi_makan', '37:177', 37, 177, 'فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَآءَ صَبَاحُ ٱلۡمُنذَرِينَ', 'when it lands in their courtyard, evil is the morning of those who were warned', 'بـ names the place it settles on: the punishment arrives like an army at the door', 1, 'tafsir:alusi:37:177', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:18:1:anzala_ala', 'ARC:نزل:anzala:ala', '18:1', 18, 1, 'ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ', 'Praise be to God, who sent down the Book upon His servant', 'على: from above, landing on the one chosen to carry it', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:136:anzala_ila', 'ARC:نزل:anzala:ila', '2:136', 2, 136, 'وَمَآ أُنزِلَ إِلَيۡنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبۡرَٰهِـۧمَ', 'and what was sent down to us, and what was sent down to Ibrāhīm', 'إلى: the sending ends with them — it reached them and is now theirs', 1, 'tafsir:zamakhshari:3:84', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:5:44:anzala_direct', 'ARC:نزل:anzala:direct', '5:44', 5, 44, 'وَمَن لَّمۡ يَحۡكُم بِمَآ أَنزَلَ ٱللَّهُ', 'whoever does not judge by what God sent down', 'no receiver: the thing and its Sender alone, set up as the measure', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:22:anzala_min', 'ARC:نزل:anzala:min', '2:22', 2, 22, 'وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ', 'and He sent down water from the sky', 'مِن names the start of the fall: here the descent is literal rain', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:39:6:anzala_lam', 'ARC:نزل:anzala:lam', '39:6', 39, 6, 'وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖ', 'and He sent down for you eight kinds of cattle', 'لَكُمْ: given out as your share — Zamakhsharī: decreed and shared out for you', 1, 'tafsir:zamakhshari:39:6', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:97:1:anzala_fi_zaman', 'ARC:نزل:anzala:fi', '97:1', 97, 1, 'إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ', 'We sent it down on the Night of Decree', 'في dates it: one night, all at once — so أنزل, not نزّل', 1, 'lex:raghib_mufradat:blk_mfr_eac4a5fec038980b', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:48:4:anzala_fi_wia', 'ARC:نزل:anzala:fi', '48:4', 48, 4, 'هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ', 'He is the One who sent calm down into the hearts of the believers', 'في holds it inside: the calm is set within the heart', 0, 'tafsir:alusi:48:4', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:57:25:anzala_maa', 'ARC:نزل:anzala:maa', '57:25', 57, 25, 'وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَٰبَ وَٱلۡمِيزَانَ', 'and We sent down with them the Book and the Balance', 'مَعَ: the Book goes along with the messengers, not onto them', 1, 'tafsir:alusi:57:25', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:33:nazzala_bi_sultan', 'ARC:نزل:nazzala:bi_sultan', '7:33', 7, 33, 'وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا', 'and that you set up partners with God, for which He has sent down no proof', 'بِهِ ties the proof to the claim; the denial leaves the claim with nothing at all', 1, 'tafsir:alusi:7:33', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:23:29:anzala_munzal', 'ARC:نزل:anzala:munzal', '23:29', 23, 29, 'رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ', 'My Lord, set me down in a blessed lodging, for You are the best of hosts', 'the object is a person: to lodge him, as a host lodges a guest', 1, 'lex:lane_lexicon:blk_lane_c414883efd2ae1b4', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:33:26:anzala_min_shakhs', 'ARC:نزل:anzala:min', '33:26', 33, 26, 'وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ مِن صَيَاصِيهِمۡ', 'and He brought down those of the People of the Book who had backed them, out of their fortresses', 'people brought down off the high ground that kept them safe', 0, 'tafsir:zamakhshari:33:26', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:3:nazzala_ala', 'ARC:نزل:nazzala:ala', '3:3', 3, 3, 'نَزَّلَ عَلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ', 'He has sent down upon you the Book with the truth', 'نَزَّلَ for the Qurʾān beside أَنزَلَ for the Torah and Gospel in the next words', 1, 'tafsir:zamakhshari:3:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:16:44:nazzala_ila', 'ARC:نزل:nazzala:ila', '16:44', 16, 44, 'لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ', 'so that you make clear to people what was sent down to them', 'إلى: the end point is the people it reached', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:15:9:nazzala_direct', 'ARC:نزل:nazzala:direct', '15:9', 15, 9, 'إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَٰفِظُونَ', 'It is We who sent down the Reminder, and We will guard it', NULL, 1, 'lex:raghib_mufradat:blk_mfr_1ff112ef22fce379', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:50:9:nazzala_min', 'ARC:نزل:nazzala:min', '50:9', 50, 9, 'وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا', 'and We sent down from the sky blessed water', NULL, 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:76:23:nazzala_tanzilan', 'ARC:نزل:nazzala:tanzilan', '76:23', 76, 23, 'إِنَّا نَحۡنُ نَزَّلۡنَا عَلَيۡكَ ٱلۡقُرۡءَانَ تَنزِيلٗا', 'It is We who sent the Qurʾān down upon you, part by part', 'the maṣdar after the verb presses the point: step by step', 1, 'tafsir:zamakhshari:76:23', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:41:30:tanazzala_ala', 'ARC:نزل:tanazzala:ala', '41:30', 41, 30, 'تَتَنَزَّلُ عَلَيۡهِمُ ٱلۡمَلَٰٓئِكَةُ أَلَّا تَخَافُواْ', 'the angels come down upon them: "Do not fear"', 'Form V: they come down in turns, and على names who receives them', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:210:tanazzala_bi', 'ARC:نزل:tanazzala:bi', '26:210', 26, 210, 'وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّيَٰطِينُ', 'it was not the devils who brought it down', 'تنزّل بـ: coming down carrying something — denied of the devils', 1, 'lex:raghib_mufradat:blk_mfr_d2cc452e9510be66', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:97:4:tanazzala_lazim', 'ARC:نزل:tanazzala:lazim', '97:4', 97, 4, 'تَنَزَّلُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم', 'in it the angels and the Spirit come down by leave of their Lord', 'no receiver: the time (فِيهَا) and the leave are named instead', 1, 'lex:raghib_mufradat:blk_mfr_3bd206b8bd0dbe59', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:2:tanzil_idafa_kitab', 'ARC:نزل:tanzil:idafa_kitab', '40:2', 40, 2, 'تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡعَلِيمِ', 'The sending-down of the Book is from God, the Mighty, the Knowing', 'the iḍāfa names what was sent; مِن names the Sender', 1, 'tafsir:zamakhshari:39:1', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:192:tanzil_munazzal', 'ARC:نزل:tanzil:munazzal', '26:192', 26, 192, 'وَإِنَّهُۥ لَتَنزِيلُ رَبِّ ٱلۡعَٰلَمِينَ', 'It is truly what the Lord of the worlds sent down', 'the Sender stands in the iḍāfa, so تَنزِيل means "the thing sent down"', 1, 'tafsir:zamakhshari:26:192', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:282:kataba_direct', 'ARC:كتب:kataba:direct', '2:282', 2, 282, 'فَٱكۡتُبُوهُۚ وَلۡيَكۡتُب بَّيۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِ', 'then write it down, and let a scribe write it between you fairly', 'the plain act: words set down on a page', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:183:kataba_ala', 'ARC:كتب:kataba:ala', '2:183', 2, 183, 'كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ', 'fasting is prescribed for you', 'على: written over them, so it binds them as a duty', 1, 'lex:lane_lexicon:blk_lane_097e59301c780e4f', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:51:kataba_lam', 'ARC:كتب:kataba:lam', '9:51', 9, 51, 'لَّن يُصِيبَنَآ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا', 'nothing will befall us except what God has written for us', 'لَنَا, not عَلَيْنَا: even hardship counted as good for us', 1, 'lex:raghib_mufradat:blk_mfr_934efdee292ec949', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:58:22:kataba_fi', 'ARC:كتب:kataba:fi', '58:22', 58, 22, 'أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ', 'those — He has written faith into their hearts', 'في: written into the heart so it stays fixed there', 1, 'lex:raghib_mufradat:blk_mfr_1fc34abd03346b30', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:53:kataba_maa', 'ARC:كتب:kataba:maa', '3:53', 3, 53, 'فَٱكۡتُبۡنَا مَعَ ٱلشَّٰهِدِينَ', 'so write us down among those who bear witness', 'to write a name with a group is to count him one of them', 1, 'lex:raghib_mufradat:blk_mfr_fcdcab59ebaa4639', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:58:21:kataba_qasam', 'ARC:كتب:kataba:qasam', '58:21', 58, 21, 'كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِيٓ', 'God has written: "I and My messengers will surely win"', 'what is written is a sworn sentence; the writing works like an oath', 1, 'tafsir:alusi:58:21', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:103:kitab_ala', 'ARC:كتب:kitab:ala', '4:103', 4, 103, 'إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا', 'prayer is a duty laid on the believers at set times', 'كِتَاب with على: not a book, but something written down as binding', 1, 'tafsir:zamakhshari:4:103', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:13:38:kitab_lam', 'ARC:كتب:kitab:lam', '13:38', 13, 38, 'لِكُلِّ أَجَلٖ كِتَابٞ', 'for every term there is a writing', 'لِـ: each term has its own written limit', 1, 'lex:raghib_mufradat:blk_mfr_7ec37251e9346905', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:129:aziz_allah', 'ARC:عزز:aziz:allah', '2:129', 2, 129, 'إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ', 'You are the Mighty, the Wise', 'might paired with wisdom: the commonest pairing', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:78:aziz_insan', 'ARC:عزز:aziz:insan', '12:78', 12, 78, 'يَٰٓأَيُّهَا ٱلۡعَزِيزُ إِنَّ لَهُۥٓ أَبٗا شَيۡخٗا كَبِيرٗا', 'O ʿAzīz, he has a father, a very old man', 'a title of office: the man who holds power in Egypt', 1, 'tafsir:zamakhshari:12:30', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:41:41:aziz_shay', 'ARC:عزز:aziz:shay', '41:41', 41, 41, 'وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٞ', 'and it is a mighty Book', 'of a thing: hard to reach, beyond being matched or broken', 1, 'lex:raghib_mufradat:blk_mfr_692b57841ecbb217', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:128:aziz_ala_amr', 'ARC:عزز:aziz:ala', '9:128', 9, 128, 'عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ', 'your suffering weighs heavy on him', 'على with a matter as subject: it is hard on him', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:11:91:aziz_ala_shakhs', 'ARC:عزز:aziz:ala', '11:91', 11, 91, 'وَمَآ أَنتَ عَلَيۡنَا بِعَزِيزٖ', 'and you are not one we hold dear', 'على with a person as subject: dear to us, someone we would spare', 0, 'tafsir:zamakhshari:11:91', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:5:54:aziz_ala_qawm', 'ARC:عزز:aziz:ala', '5:54', 5, 54, 'أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِينَ أَعِزَّةٍ عَلَى ٱلۡكَٰفِرِينَ', 'humble with the believers, hard against the deniers', 'على here is "against": the hardness faces the enemy', 0, 'tafsir:zamakhshari:5:54', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:18:34:aazz_tafdil', 'ARC:عزز:aazz:tafdil', '18:34', 18, 34, 'أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا', 'I have more wealth than you, and more men behind me', NULL, 1, 'tafsir:zamakhshari:18:34', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:26:aazza_fil', 'ARC:عزز:aazza:fil', '3:26', 3, 26, 'وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ', 'You raise whom You will and bring low whom You will', 'Form IV: God gives might to someone, paired with its opposite', 1, 'lex:raghib_mufradat:blk_mfr_75c60727551ed388', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:36:14:azzaza_bi', 'ARC:عزز:azzaza:bi', '36:14', 36, 14, 'فَعَزَّزۡنَا بِثَالِثٖ', 'so We strengthened them with a third', 'بـ names what the strength comes from: one more messenger', 1, 'tafsir:zamakhshari:36:14', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:38:23:azza_fi', 'ARC:عزز:azza:fi', '38:23', 38, 23, 'وَعَزَّنِي فِي ٱلۡخِطَابِ', 'and he got the better of me in argument', 'في names the field where one beats the other', 1, 'lex:raghib_mufradat:blk_mfr_71b667888a9d6383', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:17:105:nazala_lazim', 'ARC:نزل:nazala:lazim', '17:105', 17, 105, 'وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَ', 'With the truth We sent it down, and with the truth it came down', 'the same motion, now of revelation; بِالْحَقِّ goes along with it and governs nothing', 0, 'lex:raghib_mufradat:blk_mfr_c58dde854b5fd680', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:48:26:anzala_ala', 'ARC:نزل:anzala:ala', '48:26', 48, 26, 'فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ', 'then God sent down His calm upon His Messenger and upon the believers', 'what lands from above can be a state of heart, not only words', 0, 'lex:raghib_mufradat:blk_mfr_f9017f7a9a4a37c7', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:59:21:anzala_ala', 'ARC:نزل:anzala:ala', '59:21', 59, 21, 'لَوۡ أَنزَلۡنَا هَٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلٖ لَّرَأَيۡتَهُۥ خَٰشِعٗا مُّتَصَدِّعٗا', 'Had We sent this Qurʾān down upon a mountain, you would have seen it humbled, split apart', 'the weight of على made visible: what lands on the receiver presses on him', 0, 'lex:raghib_mufradat:blk_mfr_c8e02b4010e23968', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:28:24:anzala_ila', 'ARC:نزل:anzala:ila', '28:24', 28, 24, 'رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ', 'My Lord, I am in need of whatever good You send down to me', 'not revelation: any good that comes from above and reaches a person', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:2:anzala_direct', 'ARC:نزل:anzala:direct', '12:2', 12, 2, 'إِنَّآ أَنزَلۡنَٰهُ قُرۡءَٰنًا عَرَبِيّٗا لَّعَلَّكُمۡ تَعۡقِلُونَ', 'We sent it down as an Arabic Qurʾān, so that you may understand', 'with no receiver named, the words that follow say what shape it came in', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:57:25:anzala_direct', 'ARC:نزل:anzala:direct', '57:25', 57, 25, 'وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ', 'and We sent down iron, in which is great might', 'iron "sent down": made and given from above — Rāghib: sending down a thing or its causes', 0, 'lex:raghib_mufradat:blk_mfr_74dddc506a52d894', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:78:14:anzala_min', 'ARC:نزل:anzala:min', '78:14', 78, 14, 'وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا', 'and We sent down from the rain-clouds water pouring in torrents', 'the start point can be the clouds themselves', 0, 'lex:raghib_mufradat:blk_mfr_9c1750575092408a', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:10:59:anzala_lam', 'ARC:نزل:anzala:lam', '10:59', 10, 59, 'أَرَءَيۡتُم مَّآ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقٖ', 'Have you seen what God sent down for you of provision?', 'the لـ turns the sending into a gift laid out for use', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:185:anzala_fi_zaman', 'ARC:نزل:anzala:fi', '2:185', 2, 185, 'شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ', 'the month of Ramaḍān, in which the Qurʾān was sent down', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:24:1:anzala_fi_wia', 'ARC:نزل:anzala:fi', '24:1', 24, 1, 'وَأَنزَلۡنَا فِيهَآ ءَايَٰتِۭ بَيِّنَٰتٖ', 'and We sent down in it clear signs', 'here the container is the sūra itself', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:7:157:anzala_maa', 'ARC:نزل:anzala:maa', '7:157', 7, 157, 'ٱلنُّورَ ٱلَّذِيٓ أُنزِلَ مَعَهُۥٓ', 'the light that was sent down with him', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:40:nazzala_bi_sultan', 'ARC:نزل:nazzala:bi_sultan', '12:40', 12, 40, 'مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٍ', 'God has sent down no proof for them', 'the same frame with أَنزَلَ: no warrant for the names they invented', 0, 'tafsir:zamakhshari:12:40', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:25:32:nazzala_ala', 'ARC:نزل:nazzala:ala', '25:32', 25, 32, 'لَوۡلَا نُزِّلَ عَلَيۡهِ ٱلۡقُرۡءَانُ جُمۡلَةٗ وَٰحِدَةٗ', 'Why was the Qurʾān not sent down upon him all at once?', 'the doubled form with جُمْلَةً وَاحِدَةً: here it can only mean plain "sent down"', 0, 'tafsir:zamakhshari:25:32', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:5:112:nazzala_ala', 'ARC:نزل:nazzala:ala', '5:112', 5, 112, 'هَلۡ يَسۡتَطِيعُ رَبُّكَ أَن يُنَزِّلَ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ', 'Can your Lord send down upon us a table from the sky?', NULL, 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:47:20:nazzala_direct', 'ARC:نزل:nazzala:direct', '47:20', 47, 20, 'لَوۡلَا نُزِّلَتۡ سُورَةٞۖ فَإِذَآ أُنزِلَتۡ سُورَةٞ مُّحۡكَمَةٞ', '"If only a sūra were sent down!" Then when a firm sūra is sent down …', 'both forms in one verse: نُزِّلَت asked for, أُنزِلَت received', 0, 'lex:raghib_mufradat:blk_mfr_f7bfb1f4ef723a46', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:15:21:nazzala_direct', 'ARC:نزل:nazzala:direct', '15:21', 15, 21, 'وَمَا نُنَزِّلُهُۥٓ إِلَّا بِقَدَرٖ مَّعۡلُومٖ', 'and We send it down only in a known measure', NULL, 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:17:106:nazzala_tanzilan', 'ARC:نزل:nazzala:tanzilan', '17:106', 17, 106, 'وَنَزَّلۡنَٰهُ تَنزِيلٗا', 'and We sent it down in stages', 'Zamakhsharī: in step with events', 0, 'tafsir:zamakhshari:17:106', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:222:tanazzala_ala', 'ARC:نزل:tanazzala:ala', '26:222', 26, 222, 'تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِيمٖ', 'they come down upon every lying sinner', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:19:64:tanazzala_lazim', 'ARC:نزل:tanazzala:lazim', '19:64', 19, 64, 'وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَ', 'We do not come down except by the command of your Lord', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:32:2:tanzil_idafa_kitab', 'ARC:نزل:tanzil:idafa_kitab', '32:2', 32, 2, 'تَنزِيلُ ٱلۡكِتَٰبِ لَا رَيۡبَ فِيهِ مِن رَّبِّ ٱلۡعَٰلَمِينَ', 'The sending-down of the Book — no doubt in it — is from the Lord of the worlds', NULL, 0, 'tafsir:zamakhshari:32:2', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:41:2:tanzil_munazzal', 'ARC:نزل:tanzil:munazzal', '41:2', 41, 2, 'تَنزِيلٞ مِّنَ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ', 'Sent down from the Most Merciful, the Most Kind', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:36:12:kataba_direct', 'ARC:كتب:kataba:direct', '36:12', 36, 12, 'وَنَكۡتُبُ مَا قَدَّمُواْ وَءَاثَٰرَهُمۡ', 'and We record what they sent ahead and what they left behind', 'the object is deeds: written so they can be repaid', 0, 'lex:raghib_mufradat:blk_mfr_7c9b8e061243e4d2', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:6:54:kataba_ala', 'ARC:كتب:kataba:ala', '6:54', 6, 54, 'كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ', 'your Lord has bound Himself to mercy', 'written on Himself: He takes the duty on', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:154:kataba_ala', 'ARC:كتب:kataba:ala', '3:154', 3, 154, 'لَبَرَزَ ٱلَّذِينَ كُتِبَ عَلَيۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡ', 'those for whom death was written would have gone out to where they lay dead', 'the same على, now fate rather than law', 0, 'lex:raghib_mufradat:blk_mfr_1b72ae7504a3010d', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:5:21:kataba_lam', 'ARC:كتب:kataba:lam', '5:21', 5, 21, 'ٱدۡخُلُواْ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِي كَتَبَ ٱللَّهُ لَكُمۡ', 'enter the holy land which God has written for you', NULL, 0, 'lex:raghib_mufradat:blk_mfr_a1f427fd32d52c66', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:21:105:kataba_fi', 'ARC:كتب:kataba:fi', '21:105', 21, 105, 'وَلَقَدۡ كَتَبۡنَا فِي ٱلزَّبُورِ', 'We wrote in the Psalms', NULL, 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:4:24:kitab_ala', 'ARC:كتب:kitab:ala', '4:24', 4, 24, 'كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡ', 'God''s decree upon you', NULL, 0, 'tafsir:zamakhshari:4:24', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:15:4:kitab_lam', 'ARC:كتب:kitab:lam', '15:4', 15, 4, 'وَمَآ أَهۡلَكۡنَا مِن قَرۡيَةٍ إِلَّا وَلَهَا كِتَابٞ مَّعۡلُومٞ', 'We never destroyed a town but it had a known, written term', 'Zamakhsharī: its term, written in the Tablet', 0, 'tafsir:zamakhshari:15:4', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:9:aziz_allah', 'ARC:عزز:aziz:allah', '26:9', 26, 9, 'وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِيزُ ٱلرَّحِيمُ', 'and your Lord is truly the Mighty, the Merciful', 'the refrain of al-Shuʿarāʾ: might joined to mercy after each story of punishment', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:54:42:aziz_allah', 'ARC:عزز:aziz:allah', '54:42', 54, 42, 'فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزٖ مُّقۡتَدِرٍ', 'so We seized them with the seizing of One Mighty, All-Powerful', NULL, 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:44:49:aziz_insan', 'ARC:عزز:aziz:insan', '44:49', 44, 49, 'ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ', 'Taste! You are the "mighty", the "noble"!', 'said in mockery to one who claimed might', 0, 'tafsir:ibn_ashur:44:49', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:48:3:aziz_shay', 'ARC:عزز:aziz:shay', '48:3', 48, 3, 'وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا', 'and that God may help you with a mighty help', NULL, 0, 'tafsir:zamakhshari:48:3', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:14:20:aziz_ala_amr', 'ARC:عزز:aziz:ala', '14:20', 14, 20, 'وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٖ', 'and that is no hard thing for God', 'the same frame, denied of God', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:11:92:aziz_ala_shakhs', 'ARC:عزز:aziz:ala', '11:92', 11, 92, 'أَرَهۡطِيٓ أَعَزُّ عَلَيۡكُم مِّنَ ٱللَّهِ', 'Is my clan dearer to you than God?', 'the elative answers them in the same frame', 0, 'tafsir:alusi:11:92', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:63:8:aazz_tafdil', 'ARC:عزز:aazz:tafdil', '63:8', 63, 8, 'لَيُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّ', 'the mightier will surely drive out the lowlier from it', 'the hypocrite''s boast, answered in the next words', 0, NULL, 2);
